import{_ as a,o as t,c as o,a2 as s}from"./chunks/framework.Cmuzzkcw.js";const u=JSON.parse('{"title":"Philosophy","description":"","frontmatter":{},"headers":[],"relativePath":"guide/philosophy.md","filePath":"guide/philosophy.md"}'),i={name:"guide/philosophy.md"};function r(n,e,d,l,c,p){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="philosophy" tabindex="-1">Philosophy <a class="header-anchor" href="#philosophy" aria-label="Permalink to &quot;Philosophy&quot;">​</a></h1><p class="phil-lead"> Express is excellent. But every Express codebase eventually diverges: routes defined differently across files, validation scattered or missing, error shapes inconsistent between endpoints, no shared vocabulary between services. Teams spend energy on glue code instead of product logic. </p><p><strong>BananaJS is the one shape your team agrees on.</strong> It sits on top of Express — familiar runtime, same deployment model — and adds decorator routing, automatic validation, typed error handling, and a DI-ready module system. The result: every endpoint in every service looks the same, behaves the same, and can be tested the same way.</p><h2 id="four-ideas-drive-the-product" tabindex="-1">Four ideas drive the product <a class="header-anchor" href="#four-ideas-drive-the-product" aria-label="Permalink to &quot;Four ideas drive the product&quot;">​</a></h2><div class="phil-principles"><div class="phil-card phil-teal"><p><strong>⚡ Conventions over configuration</strong></p><p>A <code>@Controller</code> class, Validation schema, a <code>createModule</code> binding — that is the full mental model. You do not configure a router, register error middleware manually, or wire validators to handlers. The framework does it; you write business logic.</p></div><div class="phil-card phil-gold"><p><strong>🧩 Heavy is optional</strong></p><p>The core is lean — routing, validation, responses, errors, DI. Everything heavier (ORMs, observability, auth, caching, rate limiting, multi-tenancy, WebSocket) is a plugin or a decorator behind a peer dependency. You install what you need; nothing else is in your bundle.</p></div><div class="phil-card phil-purple"><p><strong>🏛️ DDD when you want it</strong></p><p>Start with a flat controller. When the model warrants it, introduce <code>createModule</code> feature slices with domain entities, repository ports, and infrastructure adapters — no forced ceremony. The <code>@banana-universe/ddd</code> package and <code>bjs generate module</code> scaffold exactly this layered structure; you adopt at your own pace.</p></div><div class="phil-card phil-coral"><p><strong>🤖 AI as a first-class citizen</strong></p><p>The <code>bjs</code> CLI ships AI-assisted workflows: generate a layered module from a description or schema, review and scaffold tests, explain code, and more. The LLM layer supports Ollama (default), llama.cpp, OpenAI, and Anthropic. See <a href="/banana-universe/tooling/ai-commands.html">AI commands</a>.</p></div></div><h2 id="what-bananajs-is-not" tabindex="-1">What BananaJS is not <a class="header-anchor" href="#what-bananajs-is-not" aria-label="Permalink to &quot;What BananaJS is not&quot;">​</a></h2><div class="phil-nolist"><ul><li><strong>A full-stack framework.</strong> It does not include templating, SSR, a built-in database, or opinionated auth. It gives you the HTTP layer and lets you choose everything else.</li><li><strong>A NestJS replacement.</strong> BananaJS is intentionally smaller. If you need its full reflection-based DI, module graph, interceptors, and pipes, NestJS is the right tool. If you want NestJS-style DX on a fraction of the dependency surface, BananaJS is built for that.</li></ul></div><hr><p>Read the <a href="/banana-universe/guide/quickstart.html">Quickstart</a> to see these ideas in code in five minutes.</p>',9)])])}const m=a(i,[["render",r]]);export{u as __pageData,m as default};
